import numpy as np
import pandas as pd

from solar import validate


def make_clean_df():
    ### Creates a DataFrame with 3 columns: timestamp, power-w and irradiance_wm2
    # and three rows, one per hour generated by pd.date_range()
    return pd.DataFrame({
        # Generates three consecutive hourly timestamps starting from midnight Jan 1, 2020 in UTC:
        # 2020-01-01 00:00:00+00:00
        # 2020-01-01 01:00:00+00:00
        # 2020-01-01 02:00:00+00:00
        "timestamp": pd.date_range("2020-01-01", periods=3, freq="h", tz="UTC"),
        "power_w": [0.0, 100.0, 200.0],
        "irradiance_wm2": [0.0, 150.0, 300.0],
    })

def test_missing_values_passes_on_clean_data():
    df = make_clean_df()
    assert validate.check_missing_values(df) == []

def test_missing_values_catches_gaps():
    df = make_clean_df()
    df.loc[1, "power_w"] = np.nan

    problems = validate.check_missing_values(df)

    assert problems == ["power_w: 1 missing values"]

def test_duplicate_timestamps_passes_on_clean_data():
    assert validate.check_duplicate_timestamps(make_clean_df()) == []

def test_duplicate_timestamps_catches_repeated_row():
    df = make_clean_df()
    bad = pd.concat([df, df.iloc[[0]]], ignore_index=True)   # first row added again

    problems = validate.check_duplicate_timestamps(bad)

    assert problems == ['1 duplicate timestamps']

def test_night_time_power_passes_on_clean_data():
    assert validate.check_night_time_power(make_clean_df()) == []

def test_check_night_time_power_catches_non_zero_row():
    df = make_clean_df()

    df.loc[0, "irradiance_wm2"] = 0.0
    df.loc[0, "power_w"] = 50   # location[row 0, column power_w]

    problems = validate.check_night_time_power(df)

    assert problems == ['1 hours where irradiance is zero but power output is not.']

def test_expected_hours_passes_on_clean_data():
    df = pd.DataFrame({ # need to create a new DataFrame with 8784 rows: a full year
        "timestamp": pd.date_range("2020-01-01", periods=8784, freq="h", tz="UTC"),
        "irradiance_wm2": [0.0] * 8784,
        "power_w": [0.0] * 8784,
    })

    problems = validate.check_expected_hours(df, "2020", "2020")
    assert problems == []

def test_check_expected_hours_catches_not_matching_years_requested():
    df = pd.DataFrame({  # need to create a new DataFrame for an hourly data in a year - 8784 rows:
                         # a full year (leap year: 366 days * 24hr)
        "timestamp": pd.date_range("2020-01-01", periods=8785, freq="h", tz="UTC"),
        "irradiance_wm2": [0.0] * 8785,
        "power_w": [0.0] * 8785,
    })
    problems = validate.check_expected_hours(df, "2020", "2020")
    assert problems == ["expected 8784 hourly rows for 2020 - 2020, got 8785"]

def test_value_ranges_passes_on_clean_data():
    assert validate.check_value_ranges(make_clean_df()) == []

def test_value_ranges_catches_negative_values():
    df = make_clean_df()
    df.loc[1, "power_w"] = -10
    problems = validate.check_value_ranges(df)
    assert problems == ['1 hours where irradiance or power is negative']